/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(pnl_Item);

        // 수신일 현재일자로 설정
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_RcvDd.setValue(scwin.vCurDate);

        // 신용등급수신정보 조회
        scwin.selectCrdtgrdRcvInfo();

        // 파일업로드 데이터셋 초기화

        // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        file.hide();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30202.onpageload" });
    }
};

