/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {

};

/**
 * @method
 * @name selectCrdtgrdRcvInfo
 * @description 신용등급수신정보 조회
 * @returns {void}
 * @hidden N
 */
scwin.selectCrdtgrdRcvInfo = function() {
    let dsNm = 'BNS_CLS_CRDTGRD_RCV_INFO';
    let qryId = 'lds.stf.bnscls.select.listCrdtgrdRcvInfo';
    let param = '&{P}V_RCV_DD=' + edt_RcvDd.getValue();
    $c.bns.fn_SearchBns('ULDBNS30202.xml', dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name selectCrdtgrdRcvInfoDtl
 * @description 신용등급수신정보상세 조회
 * @param {*} p_curRow p_curRow
 * @returns {void}
 * @hidden N
 */
scwin.selectCrdtgrdRcvInfoDtl = function(p_curRow) {
    if (p_curRow === undefined || p_curRow === "") {
        p_curRow = dts_List.getRowPosition();
    }
    let dsNm = 'BNS_CLS_CRDTGRD_RCV_INFO_DTL';
    let qryId = 'lds.stf.bnscls.select.listCrdtgrdRcvInfoDtl';
    let param = '&{P}V_RCV_DD=' + dts_List.getCellData(p_curRow, "RCV_DD");
    param += '&{P}V_CREDIT_VALU_INST_CD=' + dts_List.getCellData(p_curRow, "CREDIT_VALU_INST_CD");
    $c.bns.fn_SearchBns('ULDBNS30202.xml', dts_Detail, dsNm, qryId, param);
};

/**
 * @method
 * @name save
 * @description 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (!await scwin.checkBefSave()) {
        return;
    }
    if (!confirm(scwin.setTrsMsg("S"))) return false;
    let url = "/bns/CreditValu.do?method=saveCreditGradRcvfInfo";
    url += "&SCREN_ID=" + 'ULDBNS30202.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&EMP_NO=" + js_emp_no;
    // dts_DtlInfo.UseChangeInfo = "False";

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};

/**
 * @method
 * @name checkBefSave
 * @description 저장 전 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkBefSave = async function() {
    let isOK = true;
    let nInsertCnt = 0;
    for (let k = 1; k <= dts_List.getRowCount(); k++) {
        rStat = dts_List.getRowStatus(k);
        if (rStat === TB_JOB_INSERT) {
            nInsertCnt += 1;
        }
    }
    if (nInsertCnt < 1) {
        await $c.win.alert("저장할 데이터가 없다.");
        isOK = false;
    }
    return isOK;
};

/**
 * @method
 * @name delete
 * @description 삭제
 * @returns {void}
 * @hidden N
 */
scwin.delete = function() {
    /*
    	TB_JOB_NORMAL = 0;
    	TB_JOB_INSERT = 1;
    	TB_JOB_UPDATE = 3;
    	TB_JOB_DELETE = 2;
     */

    if (dts_List.getRowCount() < 0 || dts_List.getRowPosition() < 1) {
        return;
    }
    if (!confirm(scwin.setTrsMsg("D"))) return false;

    // RowStatus 변경
    scwin.setRowStatus();
    let url = "/bns/CreditValu.do?method=deleteCreditGradRcvfInfo";
    url += "&SCREN_ID=" + 'ULDBNS30202.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_Delete.Action = $c.lc.fn_encodeNSession(url);
    trs_Delete.KeyName = "toinb_dataid4";
    trs_Delete.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Delete.Post();
};

/**
 * @method
 * @name setRowStatus
 * @description Dataset row의 상태를 변경한다.
 * @returns {void}
 * @hidden N
 */
scwin.setRowStatus = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    /*ORG SRC: dts_List.UserStatus(dts_List.RowPosition) = TB_JOB_DELETE;*/
    X = TB_JOB_DELETE;
};

/**
 * @method
 * @name setTrsMsg
 * @description set Trs Msg 처리
 * @param {String} sTrsTp sTrsTp
 * @returns {void}
 * @hidden N
 */
scwin.setTrsMsg = function(sTrsTp) {
    const sRcvt = dts_List.getCellData(dts_List.getRowPosition(), "RCV_DD");
    const sValuInstCd = dts_List.getCellData(dts_List.getRowPosition(), "CREDIT_VALU_INST_CD");
    let msg = "수신일자 : " + sRcvt + ", 평가기관 : " + sValuInstCd + "\n\n";
    if (sTrsTp === "D") {
        msg += "위 데이터를 삭제 하시겠습니까?";
    } else if (sTrsTp === "S") {
        msg += "위 데이터를 저장 하시겠습니까?";
    }
    return msg;
};

/**
 * @method
 * @name addRow
 * @description 행추가
 * @returns {void}
 * @hidden N
 */
scwin.addRow = function() {
    if (dts_List.getRowCount() >= 4) {
        return;
    }
    dts_List.insertRow();
};

/**
 * @method
 * @name selectAttach
 * @description 파일첨부
 * @returns {void}
 * @hidden N
 */
scwin.selectAttach = function() {
    file.setValue("");
    file.open();
    dts_fileList.removeAll();
    if (file.getValue() !== "") {
        const vFile = file.getValue();
        let vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm !== "") {
            dts_fileList.insertRow();
        } else {
            return;
        }
        txb_FileName.setValue(file.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_NM", vFileNm);
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_URL", file.getValue());
    }
};

/**
 * @method
 * @name fileUpload
 * @description 파일첨부
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileUpload = async function() {
    if (dts_fileList.getRowCount() === 0) {
        await $c.win.alert("업로드할 파일을 선택하세요.");
        return false;
    }
    if (!confirm("선택한 파일을 업로드 하시겠습니까?")) return false;
    let url = "/bns/CreditValu.do?method=uploadCreditGradFile";
    url += "&SCREN_ID=" + 'ULDBNS30202.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_FileUp.Action = $c.lc.fn_encodeNSession(url);
    trs_FileUp.KeyName = "toinb_dataid4";
    trs_FileUp.KeyValue = "JSP(I:pFile=dts_fileList)";
    trs_FileUp.Post();
};
